parameters.jsCode:
const topics = $json.topics || [];
const grouped = topics.reduce((acc, topic) => {
  const key = topic.subject || 'General';
  if (!acc[key]) acc[key] = [];
  acc[key].push(topic);
  return acc;
}, {});
return Object.entries(grouped).map(([subject, items]) => ({ subject, topics: items }));

